var n=`0470-hunkar-begendi`;var a=`world-0470`;var i=`TR`;var o=`western-asia`;var l=4;var r=140;var s={en:`Hünkar Beğendi`,ua:`Хюнкяр бегенді`};var d={en:`A traditional dish from Türkiye, centered on eggplant, all-purpose flour, whole cow milk, cheddar cheese. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: баклажан, пшеничне борошно універсальне, цільне коров'яче молоко, сир чедер. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Cut the vegetables evenly and roast at 200°C for about 35 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 35 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:35,i:[[`eggplant`,700,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 8 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 8 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:8,i:[[`unsalted-butter`,65,`g`],[`all-purpose-flour`,55,`g`],[`whole-cow-milk`,330,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`cheddar-cheese`,100,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 85 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 85 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:85,i:[[`lamb`,600,`g`],[`yellow-onion`,190,`g`],[`tomato`,320,`g`],[`beef-stock`,350,`ml`],[`hot-paprika`,4,`g`]]},{en:`Spoon the silky smoked-eggplant béchamel onto plates, then arrange the tender tomato-braised lamb on top.`,ua:`Викладіть на тарілки ніжний соус бешамель із печеними баклажанами, зверху додайте м’яку баранину в томатній підливі.`,t:[`layered-assembly`,`garnishing`],m:5,i:[]}];var u={slug:n,id:a,country:`TR`,region:o,servings:4,minutes:140,title:s,text:d,steps:g};export{i as country,u as default,a as id,r as minutes,o as region,l as servings,n as slug,g as steps,d as text,s as title};